create temporary table _hm_s(meta jsonb, metal text, gold text, ship text, care text, images text) on commit drop;
insert into _hm_s values ($hm${"pricing": {"goldSpotUsdPerOzt": 4178.2, "goldQuoteSource": "gold-api.com", "goldQuoteTimestamp": "2026-09-30T11:21:00Z", "markup": 2.0, "status": "ESTIMATE_MAKER_V2", "methodology": "price = ceil(2 x maker_cost / 10) x 10 (owner decision 2026-10-07). gold grams x density x (spot x purity + labor per gram) + quoted extras; see ../maker_cost.py. Estimated parts: chain grams per inch (solid chain), priced at the list's 100 USD/g; earring non-gold work 162 USD a pair (from the 2027 enamel quote); single = 0.6 x (UNCALIBRATED); signet equivalent widths (owner rule top + shank halved; bar signet 5 mm)."}, "approval": {"blockers": ["ESTIMATED PRICE: rings use the maker's band list; chain grams and earring work are estimates (owner approved pricing on estimates 2026-10-07).", "Grams are list or geometry estimates; no sample has been cast or weighed.", "Images are design visualizations (Higgsfield): frame 01 is the stone hero, frames 02-10 the sales set, 09 a metal colour visualization; photograph the physical piece before or after the first sale."], "etsyDraftCreationAuthorized": true, "livePublicationAuthorized": false, "authority": "Owner instruction 2026-10-07: 30 minimalist men's designs, 10 bracelets, 10 earrings (single and pair), 10 rings; images approved (\"Onayla, uret\")."}, "variantSeal": "50332f0c3f9959658167fb2bf8187b92"}$hm$::jsonb, $hm$Metal: solid 10K, 14K or 18K gold in yellow, white or rose.$hm$, $hm$Finish: solid gold, no plating, no stones.$hm$, $hm$Each piece is made to order and ships free within the United States from New Jersey. Add a gift message at checkout and it ships with the piece.$hm$, $hm$Care: solid gold does not tarnish. Wipe it with a soft cloth; a brushed finish can be refreshed by a jeweller.$hm$, $hm$The product images are design visualizations of the finished piece, and the three-metal image is a colour visualization of the same design in yellow, white and rose gold; the handmade piece may vary slightly.$hm$);

insert into public.products (
  id, org_id, sku, title, description, tags, materials, status, currency,
  price_cents, quantity, has_variations, image_url, num_images, product_type, listing_metadata
)
select f.pid, '2c254edf-2119-4079-b09e-dc672e32c1f9', f.sku, f.title,
  f.lead || E'\n\n' || f.story || E'\n\n' || s.metal || E'\n' || s.gold || E'\nSize: ' || f.size || E'\n' || f.detail
    || E'\n\n' || s.ship || E'\n\n' || s.care || E'\n\n' || s.images,
  f.tags, ARRAY['Solid gold'], 'draft', 'USD',
  (select min(x) from unnest(f.price_k) x) * 1000, 20, true, 'https://amuletta.artifactstudio.info/artifact/him26/' || f.mid || '/01.jpg', 10, f.ptype, s.meta || f.meta
from _hm f, _hm_s s
where not exists (select 1 from public.products p where p.org_id = '2c254edf-2119-4079-b09e-dc672e32c1f9' and (p.sku = f.sku or p.id = f.pid));

insert into public.product_variants (
  org_id, sku, product_id, name, properties, price_cents, quantity, weight_grams, weight_source, active, currency
)
select '2c254edf-2119-4079-b09e-dc672e32c1f9',
  f.sku || '-' || k.k || c.cc || '-' || case z.s when 'Single' then '1PC' when 'Pair' then 'PAIR'
    else replace(replace(replace(z.s, 'US ', 'US'), ' inches', 'IN'), '.', '_') end,
  p.id,
  f.name || ': ' || k.k || ' ' || c.cn || ', ' || z.s,
  jsonb_build_object('Karat', k.k, 'Metal Color', c.cn, f.axis3, z.s),
  f.price_k[(k.n - 1) * cardinality(f.sizes) + z.n] * 1000, 20,
  f.grams[(k.n - 1) * cardinality(f.sizes) + z.n], 'maker-v2-est', true, 'USD'
from _hm f
join public.products p on p.org_id = '2c254edf-2119-4079-b09e-dc672e32c1f9' and p.sku = f.sku and p.etsy_listing_id is null
cross join unnest(ARRAY['10K','14K','18K']) with ordinality k(k, n)
cross join (values ('Y','Yellow Gold'),('W','White Gold'),('R','Rose Gold')) c(cc, cn)
cross join unnest(f.sizes) with ordinality z(s, n)
on conflict (org_id, sku) do update set
  product_id = excluded.product_id, name = excluded.name, properties = excluded.properties,
  price_cents = excluded.price_cents, quantity = excluded.quantity, weight_grams = excluded.weight_grams,
  weight_source = excluded.weight_source, active = excluded.active, updated_at = now();

